/* eslint-disable */
<!-- frontend/src/views/login/RegisterPage.vue -->
<template>
  <div class="register-container">
    <div class="register-wrapper">
      <div class="register-form-container">
        <div class="register-header">
          <img :src="logo" alt="团团赚拼购" class="logo" />
          <h2>用户注册</h2>
        </div>

        <el-form
          ref="registerFormRef"
          :model="registerForm"
          :rules="registerRules"
          class="register-form"
        >
          <el-form-item prop="username">
            <el-input v-model="registerForm.username" placeholder="用户名" clearable>
              <template #prefix>
                <el-icon><User /></el-icon>
              </template>
            </el-input>
          </el-form-item>

          <el-form-item prop="nickname">
            <el-input v-model="registerForm.nickname" placeholder="昵称" clearable>
              <template #prefix>
                <el-icon><User /></el-icon>
              </template>
            </el-input>
          </el-form-item>

          <el-form-item prop="password">
            <el-input
              v-model="registerForm.password"
              type="password"
              placeholder="密码"
              show-password
            >
              <template #prefix>
                <el-icon><Lock /></el-icon>
              </template>
            </el-input>
          </el-form-item>

          <el-form-item prop="confirmPassword">
            <el-input
              v-model="registerForm.confirmPassword"
              type="password"
              placeholder="确认密码"
              show-password
            >
              <template #prefix>
                <el-icon><Lock /></el-icon>
              </template>
            </el-input>
          </el-form-item>

          <el-form-item>
            <el-button
              type="primary"
              class="register-btn"
              round
              block
              @click="handleRegister"
            >
              注 册
            </el-button>
          </el-form-item>

          <div class="register-footer">
            <el-link type="primary" @click="$router.push('/login')">
              已有账号？立即登录
            </el-link>
          </div>
        </el-form>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref } from "vue";
import { User, Lock } from "@element-plus/icons-vue";

const logo = "/assets/logo.png";
const registerFormRef = ref(null);
const registerForm = ref({
  username: "",
  nickname: "",
  password: "",
  confirmPassword: "",
});

const registerRules = {
  username: [{ required: true, message: "请输入用户名", trigger: "blur" }],
  nickname: [{ required: true, message: "请输入昵称", trigger: "blur" }],
  password: [{ required: true, message: "请输入密码", trigger: "blur" }],
  confirmPassword: [
    { required: true, message: "请确认密码", trigger: "blur" },
    {
      validator: (rule, value, callback) => {
        if (value !== registerForm.value.password) {
          callback(new Error("两次密码输入不一致"));
        } else {
          callback();
        }
      },
      trigger: "blur",
    },
  ],
};

const handleRegister = () => {
  registerFormRef.value.validate((valid) => {
    if (valid) {
      console.log("注册成功:", registerForm.value);

      fetch("http://www.groupbuyingsystem.site/api/register", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          username: registerForm.value.username,
          nickname: registerForm.value.nickname,
          password: registerForm.value.password,
        }),
      })
        .then((response) => response.json())
        .then((data) => {
          if (data.id) {
            alert("注册成功！");
            // 可以选择重定向到登录页面
            // this.$router.push('/login');
          } else {
            alert(data.message || "注册失败，请重试。");
          }
        })
        .catch((error) => {
          console.error("请求错误:", error);
          alert("注册时发生错误，请稍后再试。");
        });
    } else {
      console.log("注册失败!");
      return false;
    }
  });
};
</script>

<style lang="scss" scoped>
.register-container {
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100vh;
  background: linear-gradient(135deg, #f3f4f6, #e4e7ec);
}

.register-wrapper {
  background: white;
  border-radius: 10px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.1);
  padding: 30px;
  width: 400px;
}

.register-header {
  margin-bottom: 20px;
  text-align: center;
}

.logo {
  width: 80px;
}

.register-form {
  max-width: 350px;
  margin: 0 auto;
}

.register-btn {
  margin-top: 20px;
  padding: 10px;
  font-size: 16px;
}

.register-footer {
  margin-top: 20px;
  text-align: center;
}
</style>
